struct StridesliceNegConcatV2Tiling {
    uint64_t totalRows;
    uint64_t totalLength;
    uint64_t midCol;
    uint64_t tileLength;
    uint64_t dtypeSize;
};

class KernelStridesliceNegConcatV2 {
public:
    __aicore__ inline void Init(GM_ADDR input, GM_ADDR output,
                                const StridesliceNegConcatV2Tiling &tiling) {
        tilingData_ = tiling;

        inputGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ half *>(input),
                                     tilingData_.totalRows * tilingData_.totalLength);
        outputGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ half *>(output),
                                      tilingData_.totalRows * tilingData_.totalLength);

        uint64_t tileLen = tilingData_.tileLength;
        pipe_.InitBuffer(inQueue_, BUFFER_NUM, tileLen * sizeof(half));
        pipe_.InitBuffer(outQueue_, BUFFER_NUM, tileLen * sizeof(half));

        xFp32_ = pipe_.AllocBuf<TPipe::TBuf, float>(tileLen);
        yFp32_ = pipe_.AllocBuf<TPipe::TBuf, float>(tileLen);
    }

    __aicore__ inline void Process() {
        uint64_t totalRows = tilingData_.totalRows;
        uint64_t totalLength = tilingData_.totalLength;
        uint64_t midCol = tilingData_.midCol;

        int64_t coreNum = GetBlockNum();
        int64_t coreIdx = GetBlockIdx();
        int64_t rowsPerCore = (totalRows + coreNum - 1) / coreNum;
        int64_t rowStart = coreIdx * rowsPerCore;
        int64_t rowEnd = (rowStart + rowsPerCore > static_cast<int64_t>(totalRows))
                             ? static_cast<int64_t>(totalRows)
                             : (rowStart + rowsPerCore);

        for (int64_t r = rowStart; r < rowEnd; r++) {
            uint64_t rowBase = static_cast<uint64_t>(r) * totalLength;

            // Phase 1: Identity [0, midCol)
            if (midCol > 0) {
                ProcessRowSegment(rowBase, 0, midCol, /*negate=*/false);
            }

            // Phase 2: Negate [midCol, totalLength)
            if (midCol < totalLength) {
                ProcessRowSegment(rowBase, midCol, totalLength, /*negate=*/true);
            }
        }
    }

private:
    __aicore__ inline void ProcessRowSegment(uint64_t rowBase, uint64_t segStart,
                                              uint64_t segEnd, bool negate) {
        uint64_t tileLength = tilingData_.tileLength;
        uint64_t segLen = segEnd - segStart;
        uint64_t nTiles = (segLen + tileLength - 1) / tileLength;

        if (nTiles == 0) return;

        auto doCopyIn = [&](uint64_t tileIdx) {
            uint64_t wOffset = segStart + tileIdx * tileLength;
            uint64_t curLen = (wOffset + tileLength <= segEnd) ? tileLength
                                                               : (segEnd - wOffset);
            CopyIn(rowBase + wOffset, curLen);
        };

        auto doCompute = [&](uint64_t tileIdx) {
            uint64_t wOffset = segStart + tileIdx * tileLength;
            uint64_t curLen = (wOffset + tileLength <= segEnd) ? tileLength
                                                               : (segEnd - wOffset);
            if (negate) {
                NegateCompute(curLen);
            } else {
                IdentityCompute(curLen);
            }
        };

        auto doCopyOut = [&](uint64_t tileIdx) {
            uint64_t wOffset = segStart + tileIdx * tileLength;
            uint64_t curLen = (wOffset + tileLength <= segEnd) ? tileLength
                                                               : (segEnd - wOffset);
            CopyOut(rowBase + wOffset, curLen);
        };

        // Prologue: preload first tile
        doCopyIn(0);

        // Steady state: overlap CopyIn(t) with Compute(t-1) + CopyOut(t-1)
        for (uint64_t t = 1; t < nTiles; t++) {
            doCopyIn(t);
            doCompute(t - 1);
            doCopyOut(t - 1);
        }

        // Epilogue: compute and write last tile
        doCompute(nTiles - 1);
        doCopyOut(nTiles - 1);
    }

    // --- CopyIn: GM → UB via VECIN queue ---
    __aicore__ inline void CopyIn(uint64_t flatOffset, uint64_t curLen) {
        LocalTensor<half> xLocal = inQueue_.AllocTensor<half>();

        DataCopyExtParams copyParams;
        copyParams.blockCount = 1;
        copyParams.blockLen = static_cast<uint32_t>(curLen * sizeof(half));
        copyParams.srcStride = 0;
        copyParams.dstStride = 0;
        copyParams.rsv = 0;

        DataCopyPadExtParams<half> padParams;
        padParams.isPad = false;
        padParams.leftPadding = 0;
        padParams.rightPadding = 0;
        padParams.paddingValue = 0;

        DataCopyPad(xLocal, inputGlobal_[flatOffset], copyParams, padParams);
        inQueue_.EnQue(xLocal);
    }

    // --- Identity compute: UB-to-UB copy ---
    __aicore__ inline void IdentityCompute(uint64_t curLen) {
        LocalTensor<half> xLocal = inQueue_.DeQue<half>();
        LocalTensor<half> yLocal = outQueue_.AllocTensor<half>();

        DataCopyParams ubCopyParams;
        ubCopyParams.blockCount = 1;
        ubCopyParams.blockLen = static_cast<uint16_t>(curLen * sizeof(half));
        ubCopyParams.srcStride = 0;
        ubCopyParams.dstStride = 0;

        DataCopy(yLocal, xLocal, ubCopyParams);

        outQueue_.EnQue<half>(yLocal);
        inQueue_.FreeTensor(xLocal);
    }

    // --- Negate compute: FP16→FP32→Muls(-1)→FP16 ---
    __aicore__ inline void NegateCompute(uint64_t curLen) {
        LocalTensor<half> xLocal = inQueue_.DeQue<half>();
        LocalTensor<half> yLocal = outQueue_.AllocTensor<half>();
        uint32_t count = static_cast<uint32_t>(curLen);

        // half → float: CAST_NONE (no precision loss)
        Cast(xFp32_, xLocal, RoundMode::CAST_NONE, count);

        // y = -1.0 * x in fp32
        float negOne = -1.0f;
        Muls(yFp32_, xFp32_, negOne, count);

        // float → half: CAST_ROUND (banker's rounding)
        Cast(yLocal, yFp32_, RoundMode::CAST_ROUND, count);

        outQueue_.EnQue<half>(yLocal);
        inQueue_.FreeTensor(xLocal);
    }

    // --- CopyOut: UB → GM via VECOUT queue ---
    __aicore__ inline void CopyOut(uint64_t flatOffset, uint64_t curLen) {
        LocalTensor<half> yLocal = outQueue_.DeQue<half>();

        DataCopyExtParams copyParams;
        copyParams.blockCount = 1;
        copyParams.blockLen = static_cast<uint32_t>(curLen * sizeof(half));
        copyParams.srcStride = 0;
        copyParams.dstStride = 0;
        copyParams.rsv = 0;

        DataCopyPad(outputGlobal_[flatOffset], yLocal, copyParams);
        outQueue_.FreeTensor(yLocal);
    }

private:
    StridesliceNegConcatV2Tiling tilingData_;
    GlobalTensor<half> inputGlobal_;
    GlobalTensor<half> outputGlobal_;
    TPipe pipe_;
    TQue<TPosition::VECIN, BUFFER_NUM> inQueue_;
    TQue<TPosition::VECOUT, BUFFER_NUM> outQueue_;
    TBuf<float> xFp32_;
    TBuf<float> yFp32_;
};

