#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_strideslice_neg_concat_v2_kernel.h"

namespace ascend_kernel {

at::Tensor strideslice_neg_concat_v2(at::Tensor input) {
    // Input validation
    TORCH_CHECK(input.is_contiguous(), "Input tensor must be contiguous");
    TORCH_CHECK(input.dim() == 2, "Input tensor must be 2D (flattened from 4D [N,C,H,W])");

    auto dtype = input.scalar_type();
    TORCH_CHECK(dtype == at::kHalf || dtype == at::kFloat,
                "Input dtype must be float16 or float32");

    // Get platform info
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // Create output tensor (same shape and dtype as input)
    at::Tensor output = at::empty_like(input);

    // Extract dimensions
    int64_t totalRows = input.size(0);
    int64_t totalLength = input.size(1);
    int64_t midCol = totalLength / 2;
    int64_t dtypeSize = static_cast<int64_t>(input.element_size());

    // Compute tile length based on UB capacity
    // bufferCoefficient = 16 (accounts for double buffering + FP32 intermediates)
    // tileLength = ubSize / bufferCoefficient / dtypeSize
    int64_t bufferCoefficient = 16;
    int64_t tileLength = static_cast<int64_t>(ubSize) / bufferCoefficient / dtypeSize;

    // Align tileLength to 32-byte boundary
    int64_t alignSize = 32 / dtypeSize;
    if (alignSize > 0) {
        tileLength = (tileLength / alignSize) * alignSize;
    }
    if (tileLength < 1) {
        tileLength = alignSize > 0 ? alignSize : 1;
    }

    // Populate tiling data
    StridesliceNegConcatV2Tiling tiling;
    tiling.totalRows = static_cast<uint64_t>(totalRows);
    tiling.totalLength = static_cast<uint64_t>(totalLength);
    tiling.midCol = static_cast<uint64_t>(midCol);
    tiling.tileLength = static_cast<uint64_t>(tileLength);
    tiling.dtypeSize = static_cast<uint64_t>(dtypeSize);

    // EXEC_KERNEL_CMD: all args must be lvalues
    int64_t blockDim = coreNum;
    int64_t rowsLv = totalRows;
    int64_t lenLv = totalLength;
    int64_t midLv = midCol;
    int64_t tlLv = tileLength;
    int64_t dsLv = dtypeSize;

    EXEC_KERNEL_CMD(strideslice_neg_concat_v2_kernel, blockDim,
                    input, output, tiling, rowsLv, lenLv, midLv, tlLv, dsLv);

    return output;
}

} // namespace ascend_kernel
