        uint64_t nTiles = (segLen + tileLength_ - 1) / tileLength_;
        if (nTiles == 0) return;

        // Helper: compute tile offset and length for tile index
        auto tileOffset = [segStart, this](uint64_t tidx) __aicore__ -> uint64_t {
            return segStart + tidx * tileLength_;
