#include "kernel_operator.h"

using namespace AscendC;

constexpr int32_t BUFFER_NUM = 2;

class KernelStridesliceNegConcatV2 {
public:
    __aicore__ inline void Init(GM_ADDR input, GM_ADDR output,
                                uint64_t totalRows, uint64_t totalLength,
                                uint64_t midCol, uint64_t tileLength) {
        totalRows_ = totalRows;
        totalLength_ = totalLength;
        midCol_ = midCol;
        tileLength_ = tileLength;

        uint64_t totalElements = totalRows * totalLength;
        inputGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ half *>(input), totalElements);
        outputGlobal_.SetGlobalBuffer(reinterpret_cast<__gm__ half *>(output), totalElements);

        pipe_.InitBuffer(inQueue_, BUFFER_NUM, tileLength * sizeof(half));
        pipe_.InitBuffer(outQueue_, BUFFER_NUM, tileLength * sizeof(half));
        pipe_.InitBuffer(xFp32Buf_, tileLength * sizeof(float));
        pipe_.InitBuffer(yFp32Buf_, tileLength * sizeof(float));
        xFp32_ = xFp32Buf_.Get<float>();
        yFp32_ = yFp32Buf_.Get<float>();
    }

    __aicore__ inline void Process() {
        int64_t coreNum = GetBlockNum();
        int64_t coreIdx = GetBlockIdx();
        int64_t rowsPerCore = (totalRows_ + coreNum - 1) / coreNum;
        int64_t rowStart = coreIdx * rowsPerCore;
        int64_t rowEnd = (rowStart + rowsPerCore > static_cast<int64_t>(totalRows_))
                             ? static_cast<int64_t>(totalRows_)
                             : (rowStart + rowsPerCore);

        for (int64_t r = rowStart; r < rowEnd; r++) {
            uint64_t rowBase = static_cast<uint64_t>(r) * totalLength_;

            if (midCol_ > 0) {
                ProcessSegment(rowBase, 0, midCol_, false);
            }
            if (midCol_ < totalLength_) {
                ProcessSegment(rowBase, midCol_, totalLength_, true);
            }
        }
    }

private:
    __aicore__ inline void ProcessSegment(uint64_t rowBase, uint64_t segStart,
                                           uint64_t segEnd, bool negate) {
        uint64_t segLen = segEnd - segStart;
        uint64_t nTiles = (segLen + tileLength_ - 1) / tileLength_;
        if (nTiles == 0) return;

        // Prologue: preload first tile
        uint64_t off0 = segStart;
        uint64_t len0 = (off0 + tileLength_ <= segEnd) ? tileLength_ : (segEnd - off0);
        CopyIn(rowBase + off0, len0);

        // Steady state
        for (uint64_t t = 1; t < nTiles; t++) {
            // Preload tile t
            uint64_t offT = segStart + t * tileLength_;
            uint64_t lenT = (offT + tileLength_ <= segEnd) ? tileLength_ : (segEnd - offT);
            CopyIn(rowBase + offT, lenT);

            // Compute tile t-1
            uint64_t lenPrev = (segStart + (t - 1) * tileLength_ + tileLength_ <= segEnd)
                                   ? tileLength_
                                   : (segEnd - (segStart + (t - 1) * tileLength_));
            if (negate) {
                NegateCompute(lenPrev);
            } else {
                IdentityCompute(lenPrev);
            }

            // CopyOut tile t-1
            uint64_t offPrev = segStart + (t - 1) * tileLength_;
            CopyOut(rowBase + offPrev, lenPrev);
        }

        // Epilogue: compute and write last tile
        uint64_t offLast = segStart + (nTiles - 1) * tileLength_;
        uint64_t lenLast = (offLast + tileLength_ <= segEnd) ? tileLength_ : (segEnd - offLast);
        if (negate) {
            NegateCompute(lenLast);
        } else {
            IdentityCompute(lenLast);
        }
        CopyOut(rowBase + offLast, lenLast);
    }

    __aicore__ inline void CopyIn(uint64_t flatOffset, uint64_t cmplen) {
        LocalTensor<half> xLocal = inQueue_.AllocTensor<half>();
        DataCopyExtParams copyParams;
        copyParams.blockCount = 1;
        copyParams.blockLen = static_cast<uint32_t>(cmplen * sizeof(half));
        copyParams.srcStride = 0;
        copyParams.dstStride = 0;
        copyParams.rsv = 0;
        DataCopyPadExtParams<half> padParams;
        padParams.isPad = false;
        padParams.leftPadding = 0;
        padParams.rightPadding = 0;
        padParams.paddingValue = 0;
        DataCopyPad(xLocal, inputGlobal_[flatOffset], copyParams, padParams);
        inQueue_.EnQue(xLocal);
    }

    __aicore__ inline void IdentityCompute(uint64_t cmplen) {
        LocalTensor<half> xLocal = inQueue_.DeQue<half>();
        LocalTensor<half> yLocal = outQueue_.AllocTensor<half>();
        DataCopy(yLocal, xLocal, static_cast<uint32_t>(cmplen));
        outQueue_.EnQue<half>(yLocal);
        inQueue_.FreeTensor(xLocal);
    }

    __aicore__ inline void NegateCompute(uint64_t cmplen) {
        LocalTensor<half> xLocal = inQueue_.DeQue<half>();
        LocalTensor<half> yLocal = outQueue_.AllocTensor<half>();
        uint32_t cnt32 = static_cast<uint32_t>(cmplen);

        Cast(xFp32_, xLocal, RoundMode::CAST_NONE, cnt32);
        float negOne = -1.0f;
        Muls(yFp32_, xFp32_, negOne, cnt32);
        Cast(yLocal, yFp32_, RoundMode::CAST_ROUND, cnt32);

        outQueue_.EnQue<half>(yLocal);
        inQueue_.FreeTensor(xLocal);
    }

    __aicore__ inline void CopyOut(uint64_t flatOffset, uint64_t cmplen) {
        LocalTensor<half> yLocal = outQueue_.DeQue<half>();
        DataCopyExtParams copyParams;
        copyParams.blockCount = 1;
        copyParams.blockLen = static_cast<uint32_t>(cmplen * sizeof(half));
        copyParams.srcStride = 0;
        copyParams.dstStride = 0;
        copyParams.rsv = 0;
        DataCopyPad(outputGlobal_[flatOffset], yLocal, copyParams);
        outQueue_.FreeTensor(yLocal);
    }

private:
    uint64_t totalRows_;
    uint64_t totalLength_;
    uint64_t midCol_;
    uint64_t tileLength_;
    GlobalTensor<half> inputGlobal_;
    GlobalTensor<half> outputGlobal_;
    TPipe pipe_;
    TQue<TPosition::VECIN, BUFFER_NUM> inQueue_;
    TQue<TPosition::VECOUT, BUFFER_NUM> outQueue_;
    TBuf<TPosition::VECCALC> xFp32Buf_;
    TBuf<TPosition::VECCALC> yFp32Buf_;
    LocalTensor<float> xFp32_;
    LocalTensor<float> yFp32_;
};

extern "C" __global__ __aicore__ void strideslice_neg_concat_v2_kernel(
    GM_ADDR input, GM_ADDR output,
    uint64_t totalRows, uint64_t totalLength,
    uint64_t midCol, uint64_t tileLength) {
    KernelStridesliceNegConcatV2 kernel;
    kernel.Init(input, output, totalRows, totalLength, midCol, tileLength);
    kernel.Process();
}
